interface Pet { name: string }

const dog = { name: "Lassie", owner: "Rudd" }; // тип { name: string; owner: string }
let pet: Pet = dog; // ок: у dog есть name, лишний owner никого не волнует

interface SquareConfig { color?: string; width?: number }
function createSquare(config: SquareConfig) { return config.width ?? 0; }

// 1. Свежий литерал: ошибка
createSquare({ colour: "red", width: 100 });
// error TS2561: Object literal may only specify known properties,
// but 'colour' does not exist in type 'SquareConfig'. Did you mean to write 'color'?

// 2. Через переменную: компилируется, опечатка молча теряется
const opts = { colour: "red", width: 100 };
createSquare(opts);

// 3. Через переменную, но нет ни одного общего свойства: снова ошибка
const onlyTypo = { colour: "red" };
createSquare(onlyTypo);
// error TS2559: Type '{ colour: string; }' has no properties in common with type 'SquareConfig'.

type UserId = string & { readonly __brand: "UserId" };
type OrderId = string & { readonly __brand: "OrderId" };

function loadUser(id: UserId) { /* ... */ }

const oid = "o_1" as OrderId;
loadUser(oid);
// error TS2345: Argument of type 'OrderId' is not assignable to parameter of type 'UserId'.
