loadUser("u_1");
// error TS2345: Argument of type 'string' is not assignable to parameter of type 'UserId'.

const userId = (s: string) => s as UserId; // единственная «дверь» внутрь
loadUser(userId("u_1")); // ок

function printAll(strs: string | string[] | null) {
  if (typeof strs === "object") {
    for (const s of strs) console.log(s);
    // error TS18047: 'strs' is possibly 'null'.
  }
}

type Fish = { swim: () => void };
type Bird = { fly: () => void };

function isFish(pet: Fish | Bird): pet is Fish {
  return "swim" in pet;
}

function assertIsString(val: unknown): asserts val is string {
  if (typeof val !== "string") throw new Error("not a string");
}

function yell(str: unknown) {
  assertIsString(str);       // если мы здесь, str: string
  return str.toUpperCase();  // ок
}

type Bag = { status: "loading" | "success" | "error"; data?: string; error?: Error };

// компилируется, хотя такого состояния не бывает
const impossible: Bag = { status: "loading", data: "x", error: new Error("y") };

function show(b: Bag) {
  if (b.status === "success") return b.data.length;
  // error TS18048: 'b.data' is possibly 'undefined'.
}

type ReqState =
  | { status: "loading" }
  | { status: "success"; data: string }
  | { status: "error"; error: Error };

function render(s: ReqState) {
  switch (s.status) {
    case "loading": return "...";
    case "success": return s.data;           // s: { status: "success"; data: string }
    case "error":   return s.error.message;  // s: { status: "error"; error: Error }
    default: {
      const _exhaustive: never = s;          // здесь s уже never
      return _exhaustive;
    }
  }
}

